import {
  InsufficientStockError,
  InvalidTransitionError,
  NotFoundError,
  ValidationError,
} from "../domain/errors";
import { Order, OrderLine, OrderSnapshot, OrderState } from "../domain/order";
import { assertPositiveInteger, Product } from "../domain/product";
import type { Clock, IdGenerator, OrderRepository, ProductRepository } from "../domain/repositories";

export interface PlaceOrderCommand {
  customerId: string;
  items: ReadonlyArray<{ productId: string; quantity: number }>;
}

export class OrderService {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  /**
   * Places an order and reserves stock for every line. Either all lines are
   * reserved or none are: availability is checked for the whole order before
   * any stock is touched.
   */
  placeOrder(command: PlaceOrderCommand): OrderSnapshot {
    if (command.items.length === 0) {
      throw new ValidationError("An order must have at least one item");
    }

    const requested = new Map<string, number>();
    for (const item of command.items) {
      assertPositiveInteger(item.quantity, "quantity");
      requested.set(item.productId, (requested.get(item.productId) ?? 0) + item.quantity);
    }

    const resolved: Array<{ product: Product; quantity: number }> = [];
    for (const [productId, quantity] of requested) {
      const product = this.products.findById(productId);
      if (!product) throw new NotFoundError(`Product ${productId} not found`);
      if (!product.canReserve(quantity)) {
        throw new InsufficientStockError(productId, quantity, product.available);
      }
      resolved.push({ product, quantity });
    }

    const lines: OrderLine[] = resolved.map(({ product, quantity }) => ({
      productId: product.id,
      quantity,
      unitPriceCents: product.priceCents,
    }));
    const order = new Order(this.ids.next(), command.customerId, lines, this.clock.now());

    for (const { product, quantity } of resolved) {
      product.reserve(quantity);
      this.products.save(product);
    }
    this.orders.save(order);
    return order.toSnapshot();
  }

  getOrder(id: string): OrderSnapshot {
    return this.require(id).toSnapshot();
  }

  listOrders(state?: OrderState): OrderSnapshot[] {
    const found = state ? this.orders.findByState(state) : this.orders.findAll();
    return found.map((o) => o.toSnapshot());
  }

  /** Moves an order to the requested state, enforcing the fulfilment sequence. */
  changeState(id: string, target: OrderState): OrderSnapshot {
    if (target === "cancelled") return this.cancel(id);

    const order = this.require(id);
    order.transitionTo(target, this.clock.now());
    if (target === "shipped") {
      for (const line of order.lines) {
        const product = this.requireProduct(line.productId);
        product.ship(line.quantity);
        this.products.save(product);
      }
    }
    this.orders.save(order);
    return order.toSnapshot();
  }

  /** Advances an order to the next state in the fulfilment sequence. */
  advance(id: string): OrderSnapshot {
    const order = this.require(id);
    const next = order.nextState();
    if (!next) {
      throw new InvalidTransitionError(`Order ${id} in state '${order.state}' cannot advance`);
    }
    return this.changeState(id, next);
  }

  cancel(id: string): OrderSnapshot {
    const order = this.require(id);
    order.transitionTo("cancelled", this.clock.now());
    for (const line of order.lines) {
      const product = this.requireProduct(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    }
    this.orders.save(order);
    return order.toSnapshot();
  }

  private require(id: string): Order {
    const order = this.orders.findById(id);
    if (!order) throw new NotFoundError(`Order ${id} not found`);
    return order;
  }

  private requireProduct(id: string): Product {
    const product = this.products.findById(id);
    if (!product) throw new NotFoundError(`Product ${id} not found`);
    return product;
  }
}

